/**
 * Offline WHO LMS reference tables used by the schema-driven pediatric anthropometry calculator.
 *
 * The payloads are copied from the machine-readable raw tables in the official WHO `anthro` and
 * `anthroplus` repositories and decoded from delta-encoded integers at runtime. Do not replace them
 * with interpolated hand-written curves: a table update requires a new reviewed source/version and
 * regression fixtures.
 */

const LMS_SCALE = 100_000;

type WhoGrowthAxis = 'age-days' | 'age-months' | 'length-tenths';

interface WhoGrowthTable {
  readonly axis: WhoGrowthAxis;
  readonly start: number;
  readonly end: number;
  readonly adjusted: boolean;
  readonly encoded: string;
}

interface LmsParameters {
  readonly l: number;
  readonly m: number;
  readonly s: number;
}

const TABLES: Readonly<Record<string, WhoGrowthTable>> = {
  'who0-wfa': {
    axis: 'age-days',
    start: 0,
    end: 1826,
    adjusted: true,
    encoded:
      '',
  },
  'who0-hfa': {
    axis: 'age-days',
    start: 0,
    end: 1826,
    adjusted: false,
    encoded:
      '',
  },
  'who0-bmi': {
    axis: 'age-days',
    start: 0,
    end: 1826,
    adjusted: true,
    encoded:
      '',
  },
  'who0-hc': {
    axis: 'age-days',
    start: 0,
    end: 1826,
    adjusted: false,
    encoded:
      '',
  },
  'who0-muac': {
    axis: 'age-days',
    start: 91,
    end: 1826,
    adjusted: true,
    encoded:
      '',
  },
  'who0-wfl': {
    axis: 'length-tenths',
    start: 450,
    end: 1100,
    adjusted: true,
    encoded:
      '',
  },
  'who0-wfh': {
    axis: 'length-tenths',
    start: 650,
    end: 1200,
    adjusted: true,
    encoded:
      '',
  },
  // WHO AnthroPlus keeps the 60/121 and 229 rows as interpolation boundaries. The schema only
  // exposes the clinical ranges 60 <= age < 121 for WFA and 60 <= age < 229 for HFA/BMI.
  'who5-hfa': {
    axis: 'age-months',
    start: 60,
    end: 229,
    adjusted: false,
    encoded:
      '',
  },
  'who5-wfa': {
    axis: 'age-months',
    start: 60,
    end: 121,
    adjusted: true,
    encoded:
      '',
  },
  'who5-bmi': {
    axis: 'age-months',
    start: 60,
    end: 229,
    adjusted: true,
    encoded:
      '',
  },
};

const BASE64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';

function decodeBase64(encoded: string): Uint8Array {
  const bytes: number[] = [];
  let accumulator = 0;
  let bits = 0;
  for (const character of encoded) {
    if (character === '=') break;
    const digit = BASE64.indexOf(character);
    if (digit < 0) throw new Error('Данные LMS ВОЗ содержат недопустимый символ base64.');
    accumulator = accumulator * 64 + digit;
    bits += 6;
    if (bits >= 8) {
      bits -= 8;
      bytes.push(Math.floor(accumulator / 2 ** bits) & 0xff);
      accumulator %= 2 ** bits;
    }
  }
  return Uint8Array.from(bytes);
}

function decodeTable(table: WhoGrowthTable): Float64Array {
  const rowCount = (table.end - table.start + 1) * 2;
  const bytes = decodeBase64(table.encoded);
  const values = new Float64Array(rowCount * 3);
  let byteOffset = 0;
  let previous = 0;
  for (let index = 0; index < values.length; index += 1) {
    let encodedValue = 0;
    let shift = 0;
    while (true) {
      const byte = bytes[byteOffset];
      if (byte === undefined)
        throw new Error('Данные LMS ВОЗ закончились до декодирования всех строк.');
      byteOffset += 1;
      encodedValue += (byte & 0x7f) * 2 ** shift;
      if ((byte & 0x80) === 0) break;
      shift += 7;
      if (shift > 49) throw new Error('Данные LMS ВОЗ содержат слишком большое целое число.');
    }
    const delta = encodedValue % 2 === 0 ? encodedValue / 2 : -(encodedValue + 1) / 2;
    previous += delta;
    values[index] = previous / LMS_SCALE;
  }
  if (byteOffset !== bytes.length) throw new Error('Данные LMS ВОЗ содержат лишние байты.');
  return values;
}

const decodedTables = new Map<string, Float64Array>();

function decodedTable(id: string, table: WhoGrowthTable): Float64Array {
  const existing = decodedTables.get(id);
  if (existing) return existing;
  const decoded = decodeTable(table);
  decodedTables.set(id, decoded);
  return decoded;
}

function sexIndex(sex: string): number {
  if (sex === 'male') return 0;
  if (sex === 'female') return 1;
  throw new Error('Для стандартов роста ВОЗ требуется выбрать пол: мужской или женский.');
}

function axisPosition(
  table: WhoGrowthTable,
  axisValue: number,
): { readonly lower: number; readonly upper: number; readonly fraction: number } {
  if (!Number.isFinite(axisValue))
    throw new Error('Для стандартов роста ВОЗ требуется конечное значение возраста или размера.');
  if (table.axis === 'age-days') {
    const day = Math.round(axisValue);
    if (Math.abs(day - axisValue) > 1e-9) {
      throw new Error('Таблицы ВОЗ 0–5 требуют целый возраст в днях.');
    }
    if (day < table.start || day > table.end) {
      throw new Error(`Таблица ВОЗ доступна для возраста от ${table.start} до ${table.end} дней.`);
    }
    return { lower: day, upper: day, fraction: 0 };
  }

  if (table.axis === 'age-months') {
    if (axisValue < table.start || axisValue > table.end) {
      throw new Error(
        `Таблица ВОЗ доступна для возраста от ${table.start} до ${table.end} месяцев.`,
      );
    }
    const lower = Math.trunc(axisValue);
    const fraction = axisValue - lower;
    if (fraction <= 1e-9 || lower === table.end) {
      return { lower, upper: lower, fraction: 0 };
    }
    return { lower, upper: lower + 1, fraction };
  }

  const scaled = axisValue * 10;
  const lower = Math.trunc(scaled + 1e-9);
  const fraction = scaled - lower;
  if (lower < table.start || lower > table.end || (fraction > 1e-9 && lower + 1 > table.end)) {
    throw new Error(
      `Таблицы ВОЗ «масса к длине/росту» доступны для длины/роста от ${table.start / 10} до ${table.end / 10} см.`,
    );
  }
  return {
    lower,
    upper: fraction <= 1e-9 ? lower : lower + 1,
    fraction: fraction <= 1e-9 ? 0 : fraction,
  };
}

function rowAt(
  table: WhoGrowthTable,
  data: Float64Array,
  sex: string,
  axis: number,
): LmsParameters {
  const rowsPerSex = table.end - table.start + 1;
  const index = (sexIndex(sex) * rowsPerSex + axis - table.start) * 3;
  const l = data[index];
  const m = data[index + 1];
  const s = data[index + 2];
  if (l === undefined || m === undefined || s === undefined) {
    throw new Error('В таблице LMS ВОЗ отсутствует строка нормативов.');
  }
  return { l, m, s };
}

function interpolateLms(
  lower: LmsParameters,
  upper: LmsParameters,
  fraction: number,
): LmsParameters {
  return {
    l: lower.l + fraction * (upper.l - lower.l),
    m: lower.m + fraction * (upper.m - lower.m),
    s: lower.s + fraction * (upper.s - lower.s),
  };
}

function lmsFor(
  tableId: string,
  table: WhoGrowthTable,
  sex: string,
  axisValue: number,
): LmsParameters {
  const position = axisPosition(table, axisValue);
  const data = decodedTable(tableId, table);
  const lower = rowAt(table, data, sex, position.lower);
  if (position.fraction === 0) return lower;
  return interpolateLms(lower, rowAt(table, data, sex, position.upper), position.fraction);
}

function lmsValueAtZ(parameters: LmsParameters, z: number): number {
  if (parameters.l === 0) return parameters.m * Math.exp(parameters.s * z);
  const base = 1 + parameters.l * parameters.s * z;
  if (base <= 0) return Number.NaN;
  return parameters.m * base ** (1 / parameters.l);
}

function rawLmsZ(parameters: LmsParameters, measurement: number): number {
  if (parameters.l === 0) return Math.log(measurement / parameters.m) / parameters.s;
  return ((measurement / parameters.m) ** parameters.l - 1) / (parameters.s * parameters.l);
}

function adjustedLmsZ(parameters: LmsParameters, measurement: number): number {
  const zScore = rawLmsZ(parameters, measurement);
  if (zScore <= 3 && zScore >= -3) return zScore;
  const sd3Positive = lmsValueAtZ(parameters, 3);
  const sd3Negative = lmsValueAtZ(parameters, -3);
  const sd2Positive = lmsValueAtZ(parameters, 2);
  const sd2Negative = lmsValueAtZ(parameters, -2);
  if (![sd3Positive, sd3Negative, sd2Positive, sd2Negative].every(Number.isFinite)) {
    throw new Error('Параметры LMS ВОЗ не позволяют рассчитать скорректированный z-score.');
  }
  return zScore > 3
    ? 3 + (measurement - sd3Positive) / (sd3Positive - sd2Positive)
    : -3 + (measurement - sd3Negative) / (sd2Negative - sd3Negative);
}

export function calculateWhoGrowthZScore(
  tableId: string,
  sex: string,
  axisValue: number,
  measurement: number,
): number {
  const table = TABLES[tableId];
  if (!table) throw new Error(`Неизвестная таблица нормативов роста ВОЗ «${tableId}».`);
  if (!Number.isFinite(measurement) || measurement <= 0) {
    throw new Error('Измерения для стандартов роста ВОЗ должны быть положительными числами.');
  }
  const parameters = lmsFor(tableId, table, sex, axisValue);
  const zScore = table.adjusted
    ? adjustedLmsZ(parameters, measurement)
    : rawLmsZ(parameters, measurement);
  if (!Number.isFinite(zScore)) throw new Error('Расчёт LMS ВОЗ вернул некорректный z-score.');
  return zScore;
}

export function calculateWhoGrowthValueAtZ(
  tableId: string,
  sex: string,
  axisValue: number,
  zScore: number,
): number {
  const table = TABLES[tableId];
  if (!table) throw new Error(`Неизвестная таблица нормативов роста ВОЗ «${tableId}».`);
  if (!Number.isFinite(zScore)) throw new Error('Для кривой ВОЗ требуется корректный z-score.');
  const value = lmsValueAtZ(lmsFor(tableId, table, sex, axisValue), zScore);
  if (!Number.isFinite(value) || value <= 0) {
    throw new Error('Параметры LMS ВОЗ не позволяют построить референсную кривую.');
  }
  return value;
}

function errorFunction(value: number): number {
  const sign = value < 0 ? -1 : 1;
  const absolute = Math.abs(value);
  const t = 1 / (1 + 0.3275911 * absolute);
  const polynomial =
    1 -
    ((((1.061405429 * t - 1.453152027) * t + 1.421413741) * t - 0.284496736) * t + 0.254829592) *
      t *
      Math.exp(-absolute * absolute);
  return sign * polynomial;
}

export function calculateWhoGrowthPercentile(zScore: number): number {
  if (!Number.isFinite(zScore)) throw new Error('Для перцентиля требуется корректный z-score.');
  return Math.min(100, Math.max(0, 50 * (1 + errorFunction(zScore / Math.sqrt(2)))));
}

export function calculateWhoGrowthBand(indicator: string, zScore: number): string {
  if (!Number.isFinite(zScore))
    throw new Error('Для интерпретации ВОЗ требуется корректный z-score.');
  if (indicator === 'bmi' || indicator === 'weight-length') {
    if (zScore < -3) return 'Ниже −3 SD: выраженная худоба/истощение по этому индикатору.';
    if (zScore < -2) return 'От −3 до −2 SD: худоба/истощение по этому индикатору.';
    if (zScore > 3) return 'Выше +3 SD: ожирение по BMI-for-age.';
    if (zScore > 2) return 'Выше +2 SD: избыточная масса по BMI-for-age.';
    if (zScore > 1) return 'Выше +1 SD: риск избыточной массы по BMI-for-age.';
    return 'От −2 до +1 SD: в диапазоне без отмеченного отклонения по этому индикатору.';
  }
  if (zScore < -3) return 'Ниже −3 SD: выраженное снижение относительно возрастной нормы.';
  if (zScore < -2) return 'От −3 до −2 SD: снижение относительно возрастной нормы.';
  if (zScore > 2) return 'Выше +2 SD: выше возрастного диапазона; нужна клиническая оценка.';
  return 'От −2 до +2 SD: в диапазоне возрастной нормы по этому индикатору.';
}
